        + [M("Whose family does the speaker meet?", "the Robles family", ["the Santos family", "the Cruz family", "the Reyes family"], "pamilya Robles."), M("How are the Robles children described?", "kind", ["lazy", "rude", "careless"], "mababait."), M("What do the Robles family value in dealing with people?", "pakikisama and pakikipagkapwa-tao", ["wealth", "fame", "speed"], "pakikisama."), M("What are they known for spiritually?", "being prayerful and churchgoing", ["being wealthy", "being silent", "being tall"], "madasalin."), M("How are they in times of any challenge?", "resilient and courageous", ["weak and afraid", "angry", "careless"], "matatag."), M("Why is Bongbong thanking Lingling?", "she sent tuition money", ["she cooked for him", "she lent him a car", "she visited him"], "padala mong pang-tuition."), M("What will Bongbong do after finding a job?", "send the youngest to school", ["buy a house", "go abroad", "stop studying"], "magpapa-aral kay bunso."), M("What is the double celebration?", "his graduation and Tasha’s high school graduation", ["a wedding and a birthday", "Christmas and New Year", "a fiesta and a funeral"], "dobleng selebrasyon."), M("What did Lingling promise her parents?", "that she would never leave her siblings", ["that she would marry soon", "that she would travel", "that she would sell the house"], "hinding-hindi pababayaan."), M("What does Lingling remind them to do?", "thank God, complete the simbang gabi, and pray before sleeping", ["go shopping", "learn English", "buy gifts"], "bilin."), M("What does hinding-hindi mean?", "never ever", ["maybe", "sometimes", "usually"], "hinding-hindi."), M("What does sobra-sobra mean?", "more than enough", ["not enough", "just enough", "nothing"], "sobra-sobra.")]
