        + [F("Marunong siyang ___. (to mingle)", "makihalubilo", ["makiluto", "makikain"], "makihalubilo."), F("Marunong siyang ___. (to adapt)", "makibagay", ["makiramay", "makisaya"], "makibagay."), F("Maraming magagandang ___ ang Pilipino. (values)", "pagpapahalaga", ["pagsubok", "kagipitan"], "pagpapahalaga."), F("___ ako sa kaarawan ng kaibigan natin. (will join in singing)", "Makikikanta", ["Nakikikanta", "Nakikanta"], "makikikanta.")]
